(44, 1, 'update', 'App\\Models\\WebFooter', 1, '{\"id\":1,\"key\":\"main\",\"useful_links\":[{\"key\":\"home\",\"url\":\"\\/\"},{\"key\":\"about\",\"url\":\"\\/about\"},{\"key\":\"services\",\"url\":\"\\/services\"},{\"key\":\"blog\",\"url\":\"\\/blog\"}],\"faculty_links\":[{\"key\":\"engineering\",\"url\":\"\\/faculty\\/faculty-of-engineering\"},{\"key\":\"technology\",\"url\":\"\\/faculty\\/faculty-of-technology\"},{\"key\":\"natural\",\"url\":\"\\/faculty\\/faculty-of-natural-resources-management\"},{\"key\":\"service\",\"url\":\"\\/faculty\\/faculty-of-service-and-digitalization\"}],\"social_links\":[{\"key\":\"website\",\"label\":\"Website\",\"url\":\"https:\\/\\/www.bstu.uz\\/\"},{\"key\":\"telegram\",\"label\":\"Telegram\",\"url\":\"https:\\/\\/t.me\\/bdtu_uz_rasmiy\"},{\"key\":\"instagram\",\"label\":\"Instagram\",\"url\":\"https:\\/\\/www.instagram.com\\/bdtu.uz\"},{\"key\":\"youtube\",\"label\":\"YouTube\",\"url\":\"https:\\/\\/www.youtube.com\\/channel\\/UCzQe2GCCLZqa-aUItTAas2Q\"},{\"key\":\"facebook\",\"label\":\"Facebook\",\"url\":\"https:\\/\\/www.facebook.com\\/BDTU.UZ\"}],\"admissions_apply_url\":\"\\/apply\",\"phone\":\"+998 65 224 64 35\",\"email\":\"info@bstu.uz\",\"copyright_year\":2026,\"is_active\":true,\"created_at\":\"2026-07-16T12:36:10.000000Z\",\"updated_at\":\"2026-07-16T12:36:10.000000Z\",\"translations\":[{\"id\":1,\"web_footer_id\":1,\"locale\":\"en\",\"logo_alt\":\"BSTU\",\"description\":\"Bukhara State Technical University (BSTU) is a premier higher education and scientific research hub in Central Asia, preparing elite specialists in engineering and digital technologies.\",\"admissions_badge\":\"Admissions 2026\\/2027 Open\",\"admissions_heading\":\"Shape Your Future in Engineering & Technology\",\"admissions_description\":\"Join Bukhara State Technical University and gain access to advanced laboratories, industry-partnered curriculums, and globally recognized degrees.\",\"admissions_button_label\":\"Apply Online\",\"newsletter_title\":\"Our Newsletter\",\"newsletter_description\":\"Subscribe to receive the latest updates, event announcements, and academic news.\",\"newsletter_placeholder\":\"Your email address\",\"newsletter_success_message\":\"Thank you for subscribing.\",\"useful_links_title\":\"Useful Links\",\"faculties_title\":\"Faculties\",\"contact_title\":\"Contact Us\",\"address_line_1\":\"Bukhara city, Murtazaev street, 15\",\"address_line_2\":\"Bukhara region, Republic of Uzbekistan\",\"phone_label\":\"Phone:\",\"email_label\":\"Email:\",\"rights_text\":\"All Rights Reserved BSTU \\u00a9 2026\",\"useful_link_labels\":{\"home\":\"Home\",\"about\":\"About\",\"services\":\"Services\",\"blog\":\"Blog\"},\"faculty_link_labels\":{\"engineering\":\"Faculty of Engineering\",\"technology\":\"Faculty of Technology\",\"natural\":\"Faculty of Natural Resources Management\",\"service\":\"Faculty of Service and Digitalization\"},\"created_at\":\"2026-07-16T12:36:10.000000Z\",\"updated_at\":\"2026-07-16T15:02:28.000000Z\"},{\"id\":2,\"web_footer_id\":1,\"locale\":\"uz\",\"logo_alt\":\"BSTU\",\"description\":\"Buxoro davlat texnika universiteti (BSTU) Markaziy Osiyodagi yetakchi oliy ta\\u02bclim va ilmiy tadqiqot markazi bo\\u2018lib, muhandislik va raqamli texnologiyalar bo\\u2018yicha yuqori malakali mutaxassislar tayyorlaydi.\",\"admissions_badge\":\"2026\\/2027 qabul ochiq\",\"admissions_heading\":\"Muhandislik va texnologiyada kelajagingizni yarating\",\"admissions_description\":\"Buxoro davlat texnika universitetiga qo\\u2018shiling va ilg\\u2018or laboratoriyalar, sanoat hamkorligidagi o\\u2018quv dasturlari hamda xalqaro tan olingan diplomlarga ega bo\\u2018ling.\",\"admissions_button_label\":\"Onlayn ariza topshirish\",\"newsletter_title\":\"Bizning yangiliklarimiz\",\"newsletter_description\":\"Eng so\\u2018nggi yangiliklar, tadbir e\\u02bclonlari va akademik xabarlarni olish uchun obuna bo\\u2018ling.\",\"newsletter_placeholder\":\"Email manzilingiz\",\"newsletter_success_message\":\"Obunangiz uchun rahmat.\",\"useful_links_title\":\"Foydali havolalar\",\"faculties_title\":\"Fakultetlar\",\"contact_title\":\"Biz bilan bog\\u2018laning\",\"address_line_1\":\"Buxoro shahri, Murtazayev ko\\u2018chasi, 15\",\"address_line_2\":\"Buxoro viloyati, O\\u2018zbekiston Respublikasi\",\"phone_label\":\"Telefon:\",\"email_label\":\"Email:\",\"rights_text\":\"Barcha huquqlar himoyalangan BSTU \\u00a9 2026\",\"useful_link_labels\":{\"home\":\"Bosh sahifa\",\"about\":\"Biz haqimizda\",\"services\":\"Xizmatlar\",\"blog\":\"Blog\"},\"faculty_link_labels\":{\"engineering\":\"Muhandislik fakulteti\",\"technology\":\"Texnologiya fakulteti\",\"natural\":\"Tabiiy resurslarni boshqarish fakulteti\",\"service\":\"Xizmat ko\\u2018rsatish va raqamlashtirish fakulteti\"},\"created_at\":\"2026-07-16T12:36:10.000000Z\",\"updated_at\":\"2026-07-16T15:02:28.000000Z\"},{\"id\":3,\"web_footer_id\":1,\"locale\":\"ru\",\"logo_alt\":\"BSTU\",\"description\":\"\\u0411\\u0443\\u0445\\u0430\\u0440\\u0441\\u043a\\u0438\\u0439 \\u0433\\u043e\\u0441\\u0443\\u0434\\u0430\\u0440\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u044b\\u0439 \\u0442\\u0435\\u0445\\u043d\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u0439 \\u0443\\u043d\\u0438\\u0432\\u0435\\u0440\\u0441\\u0438\\u0442\\u0435\\u0442 (BSTU) \\u044f\\u0432\\u043b\\u044f\\u0435\\u0442\\u0441\\u044f \\u0432\\u0435\\u0434\\u0443\\u0449\\u0438\\u043c \\u0446\\u0435\\u043d\\u0442\\u0440\\u043e\\u043c \\u0432\\u044b\\u0441\\u0448\\u0435\\u0433\\u043e \\u043e\\u0431\\u0440\\u0430\\u0437\\u043e\\u0432\\u0430\\u043d\\u0438\\u044f \\u0438 \\u043d\\u0430\\u0443\\u0447\\u043d\\u044b\\u0445 \\u0438\\u0441\\u0441\\u043b\\u0435\\u0434\\u043e\\u0432\\u0430\\u043d\\u0438\\u0439 \\u0432 \\u0426\\u0435\\u043d\\u0442\\u0440\\u0430\\u043b\\u044c\\u043d\\u043e\\u0439 \\u0410\\u0437\\u0438\\u0438, \\u0433\\u043e\\u0442\\u043e\\u0432\\u044f\\u0449\\u0438\\u043c \\u0432\\u044b\\u0441\\u043e\\u043a\\u043e\\u043a\\u0432\\u0430\\u043b\\u0438\\u0444\\u0438\\u0446\\u0