(129, 1, 'update', 'App\\Models\\AboutPageContentEntry', 1, NULL, '{\"entry\":\"faculties:0\",\"payload\":{\"section\":\"facultiesList\",\"type\":\"faculty_item\",\"key\":\"faculties_0\",\"metadata\":{\"id\":\"faculty-of-engineering\",\"count\":\"6 Departments\",\"link\":\"\\/faculty\\/faculty-of-engineering\",\"color\":\"border-blue-500\\/20 hover:border-blue-500\"},\"translations\":{\"ar\":{\"name\":\"\\u0643\\u0644\\u064a\\u0629 \\u0627\\u0644\\u0647\\u0646\\u062f\\u0633\\u0629\",\"dean\":\"\\u062f. \\u062c\\u0633\\u0648\\u0631 \\u0646\\u064a\\u0645\\u0627\\u062a\\u0648\\u0641\",\"description\":\"\\u0647\\u0646\\u062f\\u0633\\u0629 \\u0627\\u0644\\u0637\\u0627\\u0642\\u0629\\u060c \\u0627\\u0644\\u0647\\u0646\\u062f\\u0633\\u0629 \\u0627\\u0644\\u0645\\u0639\\u0645\\u0627\\u0631\\u064a\\u0629\\u060c \\u0627\\u0644\\u0647\\u0646\\u062f\\u0633\\u0629 \\u0627\\u0644\\u0645\\u062f\\u0646\\u064a\\u0629\\u060c \\u0648\\u062a\\u0635\\u0645\\u064a\\u0645 \\u0627\\u0644\\u0635\\u0646\\u0627\\u0639\\u0627\\u062a \\u0627\\u0644\\u062e\\u0641\\u064a\\u0641\\u0629 \\u0648\\u0627\\u0644\\u0645\\u0646\\u0633\\u0648\\u062c\\u0627\\u062a \\u0648\\u0627\\u0644\\u0645\\u064a\\u0643\\u0627\\u0646\\u064a\\u0643\\u0627.\"},\"en\":{\"name\":\"Faculty of Engineering\",\"dean\":\"Dr. Jasur A. Nematov\",\"description\":\"Power engineering, architecture, infrastructure design, mechanics, and textile materials science.\"},\"ru\":{\"name\":\"\\u0418\\u043d\\u0436\\u0435\\u043d\\u0435\\u0440\\u043d\\u044b\\u0439 \\u0444\\u0430\\u043a\\u0443\\u043b\\u044c\\u0442\\u0435\\u0442\",\"dean\":\"\\u0414\\u043e\\u0446. \\u0416\\u0430\\u0441\\u0443\\u0440 \\u0410. \\u041d\\u0435\\u043c\\u0430\\u0442\\u043e\\u0432\",\"description\":\"\\u042d\\u043b\\u0435\\u043a\\u0442\\u0440\\u043e\\u044d\\u043d\\u0435\\u0440\\u0433\\u0435\\u0442\\u0438\\u043a\\u0430, \\u0430\\u0440\\u0445\\u0438\\u0442\\u0435\\u043a\\u0442\\u0443\\u0440\\u0430, \\u0441\\u0442\\u0440\\u043e\\u0438\\u0442\\u0435\\u043b\\u044c\\u043d\\u0