(140, 1, 'update', 'App\\Models\\AboutPageContentEntry', 1, NULL, '{\"entry\":\"faculties:3\",\"payload\":{\"section\":\"facultiesList\",\"type\":\"faculty_item\",\"key\":\"faculties_3\",\"metadata\":{\"id\":\"faculty-of-natural-resources-management\",\"count\":\"6 \\u0627\\u0644\\u0623\\u0642\\u0633\\u0627\\u0645\",\"link\":\"\\/faculty\\/faculty-of-natural-resources-management\",\"color\":\"border-amber-500\\/20 hover:border-amber-500\"},\"translations\":{\"ar\":{\"name\":\"\\u0643\\u0644\\u064a\\u0629 \\u0625\\u062f\\u0627\\u0631\\u0629 \\u0627\\u0644\\u0645\\u0648\\u0627\\u0631\\u062f \\u0627\\u0644\\u0637\\u0628\\u064a\\u0639\\u064a\\u0629\",\"dean\":\"\\u062f. \\u0639\\u0644\\u064a \\u0634\\u064a\\u0631 \\u0642\\u0631\\u0628\\u0627\\u0646\\u0648\\u0641\",\"description\":\"\\u0647\\u0646\\u062f\\u0633\\u0629 \\u0627\\u0644\\u0631\\u064a \\u0648\\u0627\\u0633\\u062a\\u0635\\u0644\\u0627\\u062d \\u0627\\u0644\\u0623\\u0631\\u0627\\u0636\\u064a\\u060c \\u0627\\u0644\\u0645\\u0646\\u0634\\u0622\\u062a \\u0627\\u0644\\u0645\\u0627\\u0626\\u064a\\u0629\\u060c \\u0647\\u0646\\u062f\\u0633\\u0629 \\u0627\\u0644\\u0633\\u064a\\u0627\\u0631\\u0627\\u062a\\u060c \\u0648\\u0627\\u0644\\u0628\\u064a\\u0626\\u0629 \\u0627\\u0644\\u0635\\u0646\\u0627\\u0639\\u064a\\u0629 \\u0648\\u0627\\u0644\\u062c\\u064a\\u0648\\u0644\\u0648\\u062c\\u064a\\u0627 \\u0627\\u0644\\u0645\\u0627\\u0626\\u064a\\u0629.\"},\"en\":{\"name\":\"Faculty of Natural Resources Management\",\"dean\":\"Dr. Alisher M. Kurbanov\",\"description\":\"Irrigation engineering, vehicle manufacturing, industrial ecology, and land management.\"},\"ru\":{\"name\":\"\\u0424\\u0430\\u043a\\u0443\\u043b\\u044c\\u0442\\u0435\\u0442 \\u0443\\u043f\\u0440\\u0430\\u0432\\u043b\\u0435\\u043d\\u0438\\u044f \\u043f\\u0440\\u0438\\u0440\\u043e\\u0434\\u043d\\u044b\\u043c\\u0438 \\u0440\\u0435\\u0441\\u0443\\u0440\\u0441\\u0430\\u043c\\u0438\",\"dean\":\"\\u0414\\u043e\\u0446. \\u0410\\u043b\\u0438\\u0448\\u0435\\u0440 \\u041c. \\