INSERT INTO `department_translations` (`id`, `department_id`, `locale`, `name`, `short_name`, `description`, `content_sections`, `meta_title`, `meta_description`, `created_at`, `updated_at`) VALUES
(1, 1, 'en', 'Electrical and Power Engineering', 'Electrical and Power Engineering', 'The Department of Electrical & Power Engineering is dedicated to education and research in power generation, transmission, electrical grids, energy auditing, and renewable energy integrations. Founded on the rich heritage of technical energy training in Bukhara, we collaborate with regional power grid administrations and industrial companies to train engineers who optimize and secure the national energy sector.', NULL, 'Electrical and Power Engineering Dept', 'The Department of Electrical & Power Engineering is dedicated to education and research in power generation, transmission, electrical grids, energy auditing, and renewable energy integrations. Founded', '2026-07-16 00:25:35', '2026-07-16 00:25:35'),
(2, 1, 'uz', 'Department of Electrical & Power Engineering', 'Electrical & Power Engineering', 'The Department of Electrical & Power Engineering is dedicated to education and research in power generation, transmission, electrical grids, energy auditing, and renewable energy integrations. Founded on the rich heritage of technical energy training in Bukhara, we collaborate with regional power grid administrations and industrial companies to train engineers who optimize and secure the national energy sector.', NULL, 'Department of Electrical & Power Engineering Dept', 'The Department of Electrical & Power Engineering is dedicated to education and research in power generation, transmission, electrical grids, energy auditing, and renewable energy integrations. Founded', '2026-07-16 00:25:35', '2026-07-16 00:25:35'),
(3, 1, 'ru', 'Электро- и теплоэнергетика', 'Электро- и теплоэнергетика', 'The Department of Electrical & Power Engineering is dedicated to education and research in power generation, transmission, electrical grids, energy auditing, and renewable energy integrations. Founded on the rich heritage of technical energy training in Bukhara, we collaborate with regional power grid administrations and industrial companies to train engineers who optimize and secure the national energy sector.', NULL, 'Электро- и теплоэнергетика Dept', 'The Department of Electrical & Power Engineering is dedicated to education and research in power generation, transmission, electrical grids, energy auditing, and renewable energy integrations. Founded', '2026-07-16 00:25:35', '2026-07-16 00:25:35'),
(4, 1, 'ar', 'هندسة الكهرباء والطاقة', 'هندسة الكهرباء والطاقة', 'The Department of Electrical & Power Engineering is dedicated to education and research in power generation, transmission, electrical grids, energy auditing, and renewable energy integrations. Founded on the rich heritage of technical energy training in Bukhara, we collaborate with regional power grid administrations and industrial companies to train engineers who optimize and secure the national energy sector.', NULL, 'هندسة الكهرباء والطاقة Dept', 'The Department of Electrical & Power Engineering is dedicated to education and research in power generation, transmission, electrical grids, energy auditing, and renewable energy integrations. Founded', '2026-07-16 00:25:35', '2026-07-16 00:25:35'),
(5, 2, 'en', 'Architecture', 'Architecture', 'The Department of Architecture was founded following the presidential instructions of 2008 to preserve and develop Bukhara\'s unique historical architectural heritage. We train architects who design modern, smart buildings that blend with Bukhara\'s historic aesthetics. Our research focuses on building aerodynamics, climate-adapted structures, and restoration methodologies of ancient brick structures.', NULL, 'Architecture Dept', 'The Department of Architecture was founded following the presidential instructions of 2008 to preserve and develop Bukhara\'s unique historical architectural heritage. We train architects who design mo', '2026-07-16 00:25:35', '2026-07-16 00:25:35'),
