INSERT INTO `service_translations` (`id`, `service_id`, `locale`, `title`, `description`, `action_label`, `created_at`, `updated_at`) VALUES
(1, 1, 'en', 'HEMIS Student Portal', 'Access your academic schedule, grades, course registration, and attendance records.', 'Login to HEMIS', '2026-07-21 10:44:39', '2026-07-21 11:27:37'),
(2, 1, 'uz', 'HEMIS talabalar portali', 'Dars jadvali, baholar, fanlarga ro‘yxatdan o‘tish va davomat ma’lumotlarini ko‘ring.', 'HEMISga kirish', '2026-07-21 10:44:39', '2026-07-21 11:27:37'),
(3, 1, 'ru', 'Студенческий портал HEMIS', 'Просматривайте расписание, оценки, регистрацию на курсы и данные посещаемости.', 'Войти в HEMIS', '2026-07-21 10:44:39', '2026-07-21 11:27:37'),
(4, 1, 'ar', 'بوابة الطالب HEMIS', 'يمكنك الوصول إلى جدولك الأكاديمي والدرجات وتسجيل المقررات وسجلات الحضور.', 'تسجيل الدخول إلى HEMIS', '2026-07-21 10:44:39', '2026-07-21 11:27:37'),
(5, 2, 'en', 'Office of the Registrar', 'Manage your academic records, requests, official transcripts, and enrollment certificates.', 'Access Registrar Office', '2026-07-21 10:44:39', '2026-07-21 11:27:38'),
(6, 2, 'uz', 'Registrator ofisi', 'Akademik yozuvlar, so‘rovlar, rasmiy transkriptlar va o‘qishga qabul sertifikatlarini boshqaring.', 'Registrator ofisiga kirish', '2026-07-21 10:44:39', '2026-07-21 11:27:38'),
(7, 2, 'ru', 'Офис регистратора', 'Управляйте академическими записями, запросами, официальными транскриптами и справками о зачислении.', 'офис регистратора', '2026-07-21 10:44:39', '2026-07-23 05:30:16'),
(8, 2, 'ar', 'مكتب المسجل', 'إدارة السجلات الأكاديمية والطلبات والكشوف الرسمية وشهادات القيد.', 'الدخول إلى مكتب المسجل', '2026-07-21 10:44:39', '2026-07-21 11:27:38'),
(9, 3, 'en', 'Distance Learning Platform', 'Join online lectures, access electronic learning resources, and participate in discussion forums.', 'Open Moodle Platform', '2026-07-21 10:44:39', '2026-07-21 11:27:38'),
(10, 3, 'uz', 'Masofaviy ta’lim platformasi', 'Onlayn ma’ruzalarga qo‘shiling, elektron o‘quv resurslaridan foydalaning va forumlarda qatnashing.', 'Moodle platformasini ochish', '2026-07-21 10:44:39', '2026-07-21 11:27:38'),
(11, 3, 'ru', 'Платформа дистанционного обучения', 'Подключайтесь к онлайн-лекциям, используйте электронные ресурсы и участвуйте в форумах.', 'Открыть Moodle', '2026-07-21 10:44:39', '2026-07-21 11:27:38'),
(12, 3, 'ar', 'منصة التعليم عن بُعد', 'انضم إلى المحاضرات عبر الإنترنت، واستخدم الموارد التعليمية الإلكترونية، وشارك في المنتديات.', 'فتح منصة Moodle', '2026-07-21 10:44:39', '2026-07-21 11:27:38'),
(13, 4, 'en', 'Contract & Invoice Portal', 'Generate your student tuition contract invoice, check payment status, and make online payments.', 'Get Tuition Invoice', '2026-07-21 10:44:39', '2026-07-21 11:27:38'),
(14, 4, 'uz', 'Shartnoma va hisob-faktura portali', 'Talabalik kontrakt hisobini yarating, to‘lov holatini tekshiring va onlayn to‘lov qiling.', 'To‘lov hisobini olish', '2026-07-21 10:44:39', '2026-07-21 11:27:38'),
(15, 4, 'ru', 'Портал договоров и счетов', 'Сформируйте счет по контракту, проверьте статус оплаты и выполните онлайн-платеж.', 'Получить счет за обучение', '2026-07-21 10:44:39', '2026-07-21 11:27:38'),
(16, 4, 'ar', 'بوابة العقود والفواتير', 'أنشئ فاتورة عقد الرسوم الدراسية، وتحقق من حالة الدفع، وقم بالدفع عبر الإنترنت.', 'الحصول على فاتورة الرسوم', '2026-07-21 10:44:39', '2026-07-21 11:27:39'),
(17, 5, 'en', 'Remote Education Management', 'Manage distance learning workflows, online learning assignments, and academic coordination tools.', 'Open Remote Platform', '2026-07-21 11:04:30', '2026-07-21 11:27:39'),
(18, 5, 'uz', 'Masofaviy ta’lim boshqaruvi', 'Masofaviy ta’lim jarayonlari, onlayn topshiriqlar va akademik muvofiqlashtirish vositalarini boshqaring.', 'Masofaviy platformani ochish', '2026-07-21 11:04:30', '2026-07-21 11:27:39'),
(19, 5, 'ru', 'Управление дистанционным обучением', 'Управляйте процессами дистанционного обучения, онлайн-заданиями и академической координацией.', 'Открыть платформу', '2026-07-21 11:04:30', '2026-07-21 11:27:39'),
(20, 5, 'ar', 'إدارة التعليم عن بُعد', 'إدارة مسارات التعليم عن بُعد والمهام الإلكترونية وأدوات التنسيق الأكاديمي.', 'فتح منصة التعليم عن بُعد', '2026-07-21 11:04:30', '2026-07-21 11:27:39'),
(21, 6, 'en', 'Anti-Corruption Hotline', 'Report corruption risks and ethics concerns through the official confidential university channel.', 'Open Telegram Bot', '2026-07-21 11:04:30', '2026-07-21 11:27:40'),
(22, 6, 'uz', 'Korrupsiyaga qarshi aloqa kanali', 'Korrupsiya xavflari va odob-axloq masalalari haqida rasmiy maxfiy kanal orqali xabar bering.', 'Telegram botni ochish', '2026-07-21 11:04:30', '2026-07-21 11:27:40'),
(23, 6, 'ru', 'Антикоррупционный канал', 'Сообщайте о коррупционных рисках и вопросах этики через официальный конфиденциальный канал университета.', 'Открыть Telegram-бот', '2026-07-21 11:04:30', '2026-07-21 11:27:40'),
(24, 6, 'ar', 'قناة مكافحة الفساد', 'أبلغ عن مخاطر الفساد والمخاوف الأخلاقية عبر القناة الجامعية الرسمية بسرية.', 'فتح بوت Telegram', '2026-07-21 11:04:30', '2026-07-21 11:27:40'),
(25, 7, 'en', 'Student Accommodation Portal', 'Apply for dormitory accommodation, track housing requests, and access residence information.', 'Open Accommodation Portal', '2026-07-21 11:04:30', '2026-07-21 11:27:40'),
(26, 7, 'uz', 'Talabalar turar joyi portali', 'Yotoqxona uchun ariza yuboring, joylashuv so‘rovlarini kuzating va turar joy ma’lumotlarini oling.', 'Turar joy portalini ochish', '2026-07-21 11:04:30', '2026-07-21 11:27:40'),
(27, 7, 'ru', 'Портал студенческого проживания', 'Подавайте заявки на общежитие, отслеживайте запросы и получайте информацию о проживании.', 'Открыть портал проживания', '2026-07-21 11:04:30', '2026-07-21 11:27:40'),
(28, 7, 'ar', 'بوابة سكن الطلاب', 'قدّم طلب السكن الجامعي، وتابع طلبات الإقامة، واطلع على معلومات السكن.', 'فتح بوابة السكن', '2026-07-21 11:04:30', '2026-07-21 11:27:40'),
(29, 8, 'en', 'Academic Timetable', 'View class schedules, academic rooms, weekly timetables, and teaching session updates.', 'View Timetable', '2026-07-21 11:04:30', '2026-07-21 11:27:41'),
(30, 8, 'uz', 'Akademik dars jadvali', 'Dars jadvali, auditoriyalar, haftalik reja va mashg‘ulot yangilanishlarini ko‘ring.', 'Jadvalni ko‘rish', '2026-07-21 11:04:30', '2026-07-21 11:27:41'),
(31, 8, 'ru', 'Академическое расписание', 'Просматривайте расписание занятий, аудитории, недельные планы и обновления учебных сессий.', 'Открыть расписание', '2026-07-21 11:04:30', '2026-07-21 11:27:41'),
(32, 8, 'ar', 'الجدول الأكاديمي', 'اعرض جداول المحاضرات والقاعات والخطط الأسبوعية وتحديثات الحصص الدراسية.', 'عرض الجدول', '2026-07-21 11:04:30', '2026-07-21 11:27:41'),
(33, 9, 'en', 'Online Payment System', 'Pay tuition, dormitory fees, library fines, and other university charges securely online.', 'Make Payment', '2026-07-21 11:04:30', '2026-07-21 11:27:41'),
(34, 9, 'uz', 'Onlayn to‘lov tizimi', 'Kontrakt, yotoqxona, kutubxona va boshqa universitet to‘lovlarini xavfsiz onlayn amalga oshiring.', 'To‘lov qilish', '2026-07-21 11:04:30', '2026-07-21 11:27:41'),
(35, 9, 'ru', 'Система онлайн-оплаты', 'Безопасно оплачивайте обучение, общежитие, библиотечные штрафы и другие университетские услуги.', 'Оплатить онлайн', '2026-07-21 11:04:30', '2026-07-21 11:27:42'),
(36, 9, 'ar', 'نظام الدفع الإلكتروني', 'ادفع الرسوم الدراسية والسكن والغرامات والخدمات الجامعية الأخرى بأمان عبر الإنترنت.', 'إجراء الدفع', '2026-07-21 11:04:30', '2026-07-21 11:27:42'),
(37, 10, 'en', 'HEMIS Teacher Portal', 'Faculty members can manage classes, gradebooks, attendance, and academic reports.', 'Login to HEMIS', '2026-07-21 11:04:30', '2026-07-21 11:27:42'),
(38, 10, 'uz', 'HEMIS o‘qituvchilar portali', 'Professor-o‘qituvchilar darslar, baholash jurnali, davomat va akademik hisobotlarni boshqaradi.', 'HEMISga kirish', '2026-07-21 11:04:30', '2026-07-21 11:27:42'),
(39, 10, 'ru', 'Портал преподавателей HEMIS', 'Преподаватели могут управлять занятиями, журналами оценок, посещаемостью и отчетами.', 'Войти в HEMIS', '2026-07-21 11:04:30', '2026-07-21 11:27:42'),
(40, 10, 'ar', 'بوابة أعضاء هيئة التدريس HEMIS', 'يمكن لأعضاء هيئة التدريس إدارة المقررات وسجلات الدرجات والحضور والتقارير الأكاديمية.', 'تسجيل الدخول إلى HEMIS', '2026-07-21 11:04:30', '2026-07-21 11:27:42'),
(41, 11, 'en', 'Digital Library', 'Search electronic books, research materials, academic publications, and library resources.', 'Open Library', '2026-07-21 11:04:30', '2026-07-21 11:27:43'),
(42, 11, 'uz', 'Raqamli kutubxona', 'Elektron kitoblar, ilmiy materiallar, akademik nashrlar va kutubxona resurslarini qidiring.', 'Kutubxonani ochish', '2026-07-21 11:04:30', '2026-07-21 11:27:43'),
(43, 11, 'ru', 'Цифровая библиотека', 'Ищите электронные книги, научные материалы, академические публикации и ресурсы библиотеки.', 'Открыть библиотеку', '2026-07-21 11:04:30', '2026-07-21 11:27:43'),
(44, 11, 'ar', 'المكتبة الرقمية', 'ابحث في الكتب الإلكترونية والمواد البحثية والمنشورات الأكاديمية وموارد المكتبة.', 'فتح المكتبة', '2026-07-21 11:04:30', '2026-07-21 11:27:43'),
(45, 12, 'en', 'Dissertations Platform', 'Access dissertation announcements, research defense materials, and scientific council information.', 'View Dissertations', '2026-07-21 11:04:30', '2026-07-21 11:27:43'),
(46, 12, 'uz', 'Dissertatsiyalar platformasi', 'Dissertatsiya e’lonlari, himoya materiallari va ilmiy kengash ma’lumotlaridan foydalaning.', 'Dissertatsiyalarni ko‘rish', '2026-07-21 11:04:30', '2026-07-21 11:27:43'),
(47, 12, 'ru', 'Платформа диссертаций', 'Получайте доступ к объявлениям о диссертациях, материалам защит и информации научного совета.', 'Смотреть диссертации', '2026-07-21 11:04:30', '2026-07-21 11:27:43'),
(48, 12, 'ar', 'منصة الرسائل العلمية', 'اطلع على إعلانات الرسائل ومواد المناقشات ومعلومات المجالس العلمية.', 'عرض الرسائل العلمية', '2026-07-21 11:04:30', '2026-07-21 11:27:44'),
(49, 13, 'en', 'Scientific Conferences', 'Register for conferences, submit papers, and follow university scientific events.', 'Open Conferences', '2026-07-21 11:04:30', '2026-07-21 11:27:44'),
(50, 13, 'uz', 'Ilmiy konferensiyalar', 'Konferensiyalarga ro‘yxatdan o‘ting, maqola yuboring va universitet ilmiy tadbirlarini kuzating.', 'Konferensiyalarni ochish', '2026-07-21 11:04:30', '2026-07-21 11:27:44'),
(51, 13, 'ru', 'Научные конференции', 'Регистрируйтесь на конференции, отправляйте статьи и следите за научными событиями университета.', 'Открыть конференции', '2026-07-21 11:04:30', '2026-07-21 11:27:44'),
(52, 13, 'ar', 'المؤتمرات العلمية', 'سجّل في المؤتمرات، وقدّم الأبحاث، وتابع الفعاليات العلمية في الجامعة.', 'فتح المؤتمرات', '2026-07-21 11:04:30', '2026-07-21 11:27:44'),
(53, 14, 'en', 'Virtual Campus Tour', 'Explore BSTU buildings, laboratories, campus spaces, and student facilities online.', 'Start Virtual Tour', '2026-07-21 11:04:30', '2026-07-21 11:27:44'),
(54, 14, 'uz', 'Virtual kampus sayohati', 'BuxDTU binolari, laboratoriyalari, kampus hududi va talabalar infratuzilmasini onlayn ko‘ring.', 'Virtual sayohatni boshlash', '2026-07-21 11:04:30', '2026-07-21 11:27:44'),
(55, 14, 'ru', 'Виртуальный тур по кампусу', 'Исследуйте здания, лаборатории, территорию кампуса и студенческую инфраструктуру онлайн.', 'Начать виртуальный тур', '2026-07-21 11:04:30', '2026-07-21 11:27:44'),
(56, 14, 'ar', 'جولة افتراضية في الحرم الجامعي', 'استكشف مباني BSTU والمختبرات ومساحات الحرم ومرافق الطلاب عبر الإنترنت.', 'بدء الجولة الافتراضية', '2026-07-21 11:04:30', '2026-07-21 11:27:44'),
(57, 15, 'en', 'KPI Monitoring System', 'Track performance indicators, departmental progress, and institutional reporting metrics.', 'Open KPI System', '2026-07-21 11:04:30', '2026-07-21 11:27:44'),
(58, 15, 'uz', 'KPI monitoring tizimi', 'Samaradorlik ko‘rsatkichlari, bo‘limlar rivoji va institutsional hisobot metrikalarini kuzating.', 'KPI tizimini ochish', '2026-07-21 11:04:30', '2026-07-21 11:27:44'),
(59, 15, 'ru', 'Система мониторинга KPI', 'Отслеживайте показатели эффективности, прогресс подразделений и отчетные метрики.', 'Открыть KPI', '2026-07-21 11:04:30', '2026-07-21 11:27:44'),
(60, 15, 'ar', 'نظام متابعة مؤشرات الأداء', 'تابع مؤشرات الأداء وتقدم الأقسام ومقاييس التقارير المؤسسية.', 'فتح نظام KPI', '2026-07-21 11:04:30', '2026-07-21 11:27:44'),
(61, 16, 'en', 'Official Telegram Channel', 'Follow official university updates, urgent notices, student news, and campus announcements.', 'Open Telegram', '2026-07-21 11:04:30', '2026-07-21 11:27:44'),
(62, 16, 'uz', 'Rasmiy Telegram kanali', 'Universitet yangiliklari, muhim xabarlar, talabalar e’lonlari va kampus ma’lumotlarini kuzating.', 'Telegramni ochish', '2026-07-21 11:04:30', '2026-07-21 11:27:44'),
(63, 16, 'ru', 'Официальный Telegram-канал', 'Следите за новостями университета, срочными уведомлениями и объявлениями кампуса.', 'Открыть Telegram', '2026-07-21 11:04:30', '2026-07-21 11:27:44'),
(64, 16, 'ar', 'قناة Telegram الرسمية', 'تابع تحديثات الجامعة الرسمية والتنبيهات العاجلة وأخبار الطلاب وإعلانات الحرم الجامعي.', 'فتح Telegram', '2026-07-21 11:04:30', '2026-07-21 11:27:44'),
(65, 17, 'en', 'University Webmail', 'Access official university email accounts for staff, departments, and academic communication.', 'Open Webmail', '2026-07-21 11:04:30', '2026-07-21 11:27:45'),
(66, 17, 'uz', 'Universitet veb-pochtasi', 'Xodimlar, bo‘limlar va akademik aloqa uchun rasmiy universitet email hisoblariga kiring.', 'Veb-pochtani ochish', '2026-07-21 11:04:30', '2026-07-21 11:27:45'),
(67, 17, 'ru', 'Университетская веб-почта', 'Откройте официальные почтовые аккаунты университета для сотрудников и подразделений.', 'Открыть Webmail', '2026-07-21 11:04:30', '2026-07-21 11:27:46'),
(68, 17, 'ar', 'البريد الإلكتروني الجامعي', 'ادخل إلى حسابات البريد الرسمية للموظفين والأقسام والتواصل الأكاديمي.', 'فتح البريد الجامعي', '2026-07-21 11:04:30', '2026-07-21 11:27:46');
