INSERT INTO `web_footer_translations` (`id`, `web_footer_id`, `locale`, `logo_alt`, `description`, `admissions_badge`, `admissions_heading`, `admissions_description`, `admissions_button_label`, `newsletter_title`, `newsletter_description`, `newsletter_placeholder`, `newsletter_success_message`, `useful_links_title`, `faculties_title`, `contact_title`, `address_line_1`, `address_line_2`, `phone_label`, `email_label`, `rights_text`, `useful_link_labels`, `faculty_link_labels`, `created_at`, `updated_at`) VALUES
(1, 1, 'en', 'BSTU', 'Bukhara State Technical University (BSTU) is a premier higher education and scientific research hub in Central Asia, preparing elite specialists in engineering and digital technologies.', 'Admissions 2026/2027 Open', 'Shape Your Future in Engineering & Technology', 'Join Bukhara State Technical University and gain access to advanced laboratories, industry-partnered curriculums, and globally recognized degrees.', 'Apply Online', 'Our Newsletter', 'Subscribe to receive the latest updates, event announcements, and academic news.', 'Your email address', 'Thank you for subscribing.', 'Useful Links', 'Faculties', 'Contact Us', 'Bukhara city, Murtazaev street, 15', 'Bukhara region, Republic of Uzbekistan', 'Phone:', 'Email:', 'All Rights Reserved BSTU © 2026', '{\"home\":\"Home\",\"about\":\"About\",\"services\":\"Services\",\"blog\":\"Blog\",\"contact\":\"Contact\"}', '{\"engineering\":\"Faculty of Engineering\",\"technology\":\"Faculty of Technology\",\"natural\":\"Faculty of Natural Resources Management\",\"service\":\"Faculty of Service and Digitalization\",\"mersy\":\"mersy\"}', '2026-07-16 07:36:10', '2026-07-23 08:29:58'),
(2, 1, 'uz', 'BDTU', 'Buxoro davlat texnika universiteti (BSTU) Markaziy Osiyodagi yetakchi oliy taʼlim va ilmiy tadqiqot markazi bo‘lib, muhandislik va raqamli texnologiyalar bo‘yicha yuqori malakali mutaxassislar tayyorlaydi.', '2026/2027 qabul ochiq', 'Muhandislik va texnologiyada kelajagingizni yarating', 'Buxoro davlat texnika universitetiga qo‘shiling va ilg‘or laboratoriyalar, sanoat hamkorligidagi o‘quv dasturlari hamda xalqaro tan olingan diplomlarga ega bo‘ling.', 'Onlayn ariza topshirish', 'Bizning yangiliklarimiz', 'Eng so‘nggi yangiliklar, tadbir eʼlonlari va akademik xabarlarni olish uchun obuna bo‘ling.', 'Email manzilingiz', 'Obunangiz uchun rahmat.', 'Foydali havolalar', 'Fakultetlar', 'Biz bilan bog‘laning', 'Buxoro shahri, Murtazayev ko‘chasi, 15', 'Buxoro viloyati, O‘zbekiston Respublikasi', 'Telefon:', 'Email:', 'Barcha huquqlar himoyalangan BSTU © 2026', '{\"home\":\"Bosh sahifa\",\"about\":\"Biz haqimizda\",\"services\":\"Xizmatlar\",\"blog\":\"Blog\",\"contact\":\"Aloqa\"}', '{\"engineering\":\"Muhandislik fakulteti\",\"technology\":\"Texnologiya fakulteti\",\"natural\":\"Tabiiy resurslarni boshqarish fakulteti\",\"service\":\"Xizmat ko\\u2018rsatish va raqamlashtirish fakulteti\",\"mersy\":\"mersy\"}', '2026-07-16 07:36:10', '2026-07-23 08:29:58'),
(3, 1, 'ru', 'Бгту', 'Бухарский государственный технический университет (BSTU) является ведущим центром высшего образования и научных исследований в Центральной Азии, готовящим высококвалифицированных специалистов в инженерии и цифровых технологиях.', 'Прием 2026/2027 открыт', 'Создайте свое будущее в инженерии и технологиях', 'Поступайте в Бухарский государственный технический университет и получите доступ к современным лабораториям, учебным программам с индустриальными партнерами и международно признанным дипломам.', 'Подать заявку онлайн', 'Наша рассылка', 'Подпишитесь, чтобы получать последние новости, объявления о событиях и академические обновления.', 'Ваш email адрес', 'Спасибо за подписку.', 'Полезные ссылки', 'Факультеты', 'Свяжитесь с нами', 'город Бухара, улица Муртазаева, 15', 'Бухарская область, Республика Узбекистан', 'Телефон:', 'Email:', 'Все права защищены BSTU © 2026', '{\"home\":\"\\u0413\\u043b\\u0430\\u0432\\u043d\\u0430\\u044f\",\"about\":\"\\u041e \\u043d\\u0430\\u0441\",\"services\":\"\\u0423\\u0441\\u043b\\u0443\\u0433\\u0438\",\"blog\":\"\\u0411\\u043b\\u043e\\u0433\",\"contact\":\"\\u043a\\u043e\\u043d\\u0442\\u0430\\u043a\\u0442\"}', '{\"engineering\":\"\\u0418\\u043d\\u0436\\u0435\\u043d\\u0435\\u0440\\u043d\\u044b\\u0439 \\u0444\\u0430\\u043a\\u0443\\u043b\\u044c\\u0442\\u0435\\u0442\",\"technology\":\"\\u0424\\u0430\\u043a\\u0443\\u043b\\u044c\\u0442\\u0435\\u0442 \\u0442\\u0435\\u0445\\u043d\\u043e\\u043b\\u043e\\u0433\\u0438\\u0439\",\"natural\":\"\\u0424\\u0430\\u043a\\u0443\\u043b\\u044c\\u0442\\u0435\\u0442 \\u0443\\u043f\\u0440\\u0430\\u0432\\u043b\\u0435\\u043d\\u0438\\u044f \\u043f\\u0440\\u0438\\u0440\\u043e\\u0434\\u043d\\u044b\\u043c\\u0438 \\u0440\\u0435\\u0441\\u0443\\u0440\\u0441\\u0430\\u043c\\u0438\",\"service\":\"\\u0424\\u0430\\u043a\\u0443\\u043b\\u044c\\u0442\\u0435\\u0442 \\u0441\\u0435\\u0440\\u0432\\u0438\\u0441\\u0430 \\u0438 \\u0446\\u0438\\u0444\\u0440\\u043e\\u0432\\u0438\\u0437\\u0430\\u0446\\u0438\\u0438\",\"mersy\":\"mersy\"}', '2026-07-16 07:36:11', '2026-07-23 08:29:58'),
(4, 1, 'ar', 'جامعة بخارا التقنية الحكومية', 'جامعة بخارى التقنية الحكومية (BSTU) هي مركز رائد للتعليم العالي والبحث العلمي في آسيا الوسطى، وتعد نخبة من المتخصصين في الهندسة والتقنيات الرقمية.', 'القبول 2026/2027 مفتوح', 'اصنع مستقبلك في الهندسة والتكنولوجيا', 'انضم إلى جامعة بخارى التقنية الحكومية واحصل على مختبرات متقدمة، ومناهج مرتبطة بالصناعة، وشهادات معترف بها عالميًا.', 'قدّم الآن', 'النشرة الإخبارية', 'اشترك لتصلك آخر التحديثات وإعلانات الفعاليات والأخبار الأكاديمية.', 'عنوان بريدك الإلكتروني', 'شكرًا لاشتراكك.', 'روابط مفيدة', 'الكليات', 'اتصل بنا', 'مدينة بخارى، شارع مورتازاييف، 15', 'منطقة بخارى، جمهورية أوزبكستان', 'الهاتف:', 'البريد الإلكتروني:', 'جميع الحقوق محفوظة BSTU © 2026', '{\"home\":\"\\u0627\\u0644\\u0631\\u0626\\u064a\\u0633\\u064a\\u0629\",\"about\":\"\\u0645\\u0646 \\u0646\\u062d\\u0646\",\"services\":\"\\u0627\\u0644\\u062e\\u062f\\u0645\\u0627\\u062a\",\"blog\":\"\\u0627\\u0644\\u0645\\u062f\\u0648\\u0646\\u0629\",\"contact\":\"\\u062a\\u0648\\u0627\\u0635\\u0644 \\u0645\\u0639\\u0646\\u0627\"}', '{\"engineering\":\"\\u0643\\u0644\\u064a\\u0629 \\u0627\\u0644\\u0647\\u0646\\u062f\\u0633\\u0629\",\"technology\":\"\\u0643\\u0644\\u064a\\u0629 \\u0627\\u0644\\u062a\\u0643\\u0646\\u0648\\u0644\\u0648\\u062c\\u064a\\u0627\",\"natural\":\"\\u0643\\u0644\\u064a\\u0629 \\u0625\\u062f\\u0627\\u0631\\u0629 \\u0627\\u0644\\u0645\\u0648\\u0627\\u0631\\u062f \\u0627\\u0644\\u0637\\u0628\\u064a\\u0639\\u064a\\u0629\",\"service\":\"\\u0643\\u0644\\u064a\\u0629 \\u0627\\u0644\\u062e\\u062f\\u0645\\u0627\\u062a \\u0648\\u0627\\u0644\\u0631\\u0642\\u0645\\u0646\\u0629\",\"mersy\":\"mersy\"}', '2026-07-16 07:36:11', '2026-07-23 08:29:58');
